import errno

FAILURES = ["ENOENT", "EACCES", "EBUSY", "EAGAIN", "EPROTO"]


def diagnose(code):
    if code == errno.ENOENT:
        return "the driver never created the node, check the device tree"
    if code == errno.EACCES:
        return "the node exists, your user is not in its group"
    if code == errno.EBUSY:
        return "another process already claimed it"
    if code == errno.EAGAIN:
        return "nothing to read yet on a non blocking descriptor"
    return "unknown, look it up in errno.h"


for name in FAILURES:
    print(name.ljust(7), "->", diagnose(getattr(errno, name)))

