import tempfile


def fake_sysfs(files):
    root = tempfile.mkdtemp(prefix="sysfs-")
    for rel, text in files.items():
        full = os.path.join(root, rel)
        os.makedirs(os.path.dirname(full), exist_ok=True)
        handle = open(full, "w")
        handle.write(text)
        handle.close()
    return root


