import errno

held = {}


def request_lines(offsets, consumer):
    for offset in offsets:
        if offset in held:
            raise OSError(errno.EBUSY, "line %d held by %s" % (offset, held[offset]))
    for offset in offsets:
        held[offset] = consumer
    return consumer


def close(consumer):
    for offset in [k for k, v in held.items() if v == consumer]:
        del held[offset]


def show():
    return sorted(held.items())


request_lines([17, 18], "wheel-left")
print("after the first claim:", show())
try:
    request_lines([18, 19], "wheel-right")
    print("the second claim went through, which it should not")
except OSError as busy:
    print("second claim refused with", errno.errorcode[busy.errno])
close("wheel-left")
print("after the holder let go:", show())
request_lines([18, 19], "wheel-right")
print("and now it fits:", show())

