           "rootfstype=ext4 rootwait quiet splash cgroup_enable=memory")


def parse_cmdline(line):
    options = {}
    flags = []
    for token in line.split():
        if "=" in token:
            key, value = token.split("=", 1)
            options.setdefault(key, []).append(value)
