import struct

CLASSES = {1: "32 bit", 2: "64 bit"}
MACHINES = {40: "arm", 62: "x86-64", 183: "aarch64", 243: "riscv"}


def build_elf(width, machine, kind):
    ident = b"\x7fELF" + bytes([width, 1, 1, 0, 0]) + b"\x00" * 7
    return ident + struct.pack("<HHI", kind, machine, 1)


SAMPLES = [("rover, cross built", build_elf(2, 183, 3)),
           ("rover, built by mistake on the laptop", build_elf(2, 62, 3)),
           ("old 32 bit driver", build_elf(1, 40, 2)),
           ("a shell script", b"#!/bin/sh\necho hello\n")]


def describe(blob):
    if blob[:4] != b"\x7fELF":
        return "not an ELF file"
    width = CLASSES.get(blob[4], "unknown class")
    kind, machine, version = struct.unpack("<HHI", blob[16:24])
    return "%s, %s, type %d" % (width, MACHINES.get(machine, "unknown machine"), kind)


for label, blob in SAMPLES:
    print(label.ljust(38), describe(blob))

